function createTtlCache<V>(defaultTtlMs: number) {
  const store = new Map<string, { value: V; expiresAt: number }>();
  return {
    set(key: string, value: V, ttlMs: number = defaultTtlMs): void {
      store.set(key, { value, expiresAt: Date.now() + ttlMs });
    },
    get(key: string, now: number = Date.now()): V | null {
      const entry = store.get(key);
      if (!entry) return null;
      if (now > entry.expiresAt) {
        store.delete(key);
        return null;
      }
      return entry.value;
    },
    has(key: string, now: number = Date.now()): boolean {
      return this.get(key, now) !== null;
    }
  };
}

