      middlewares.push(mw);
    },
    register(method: string, path: string, handler: (req: any) => Promise<any>): void {
      routes.set(`${method.toUpperCase()} ${path}`, handler);
    },
    async handle(req: { method: string; path: string; headers?: Record<string, string>; body?: any }): Promise<{ status: number; body: any }> {
      let i = 0;
      const dispatch = async (): Promise<any> => {
        if (i < middlewares.length) {
          const mw = middlewares[i++];
          return await mw(req, dispatch);
        }
        const key = `${req.method.toUpperCase()} ${req.path}`;
        const handler = routes.get(key);
        if (!handler) {
          return { status: 404, body: { error: 'Not Found' } };
        }
        return await handler(req);
      };
      return await dispatch();
    }
  };
}

