function formatServiceMetrics(metrics: { requests: number; errors: number; totalDurationMs: number }): { requests: number; errorRate: string; avgDurationMs: number } {
  if (metrics.requests <= 0) {
    return { requests: 0, errorRate: '0.00%', avgDurationMs: 0 };
  }
  const avgDurationMs = Math.round((metrics.totalDurationMs / metrics.requests) * 100) / 100;
  const errorRate = ((metrics.errors / metrics.requests) * 100).toFixed(2) + '%';
  return {
    requests: metrics.requests,
    errorRate,
    avgDurationMs
  };
}
